#import "noshi_tab_icons.h"

#include <stdlib.h>

#define ICON_SIDE 31.0f

static const char *NoshiReadNumber(const char *p, CGFloat *out) {
    while (*p == ' ' || *p == ',') ++p;
    char *end = NULL;
    double value = strtod(p, &end);
    *out = end == p ? 0 : (CGFloat)value;
    return end == p ? p : end;
}

void NoshiDrawOutline(CGContextRef context, const char *path) {
    const char *p = path;
    CGFloat v[6];
    while (*p) {
        char command = *p++;
        switch (command) {
        case 'M':
        case 'L':
            p = NoshiReadNumber(p, &v[0]);
            p = NoshiReadNumber(p, &v[1]);
            if (command == 'M') CGContextMoveToPoint(context, v[0], v[1]);
            else CGContextAddLineToPoint(context, v[0], v[1]);
            break;
        case 'C':
            for (int i = 0; i < 6; ++i) p = NoshiReadNumber(p, &v[i]);
            CGContextAddCurveToPoint(context, v[0], v[1], v[2], v[3], v[4], v[5]);
            break;
        case 'Z':
            CGContextClosePath(context);
            CGContextFillPath(context);
            CGContextBeginPath(context);
            break;
        case 'S':
            CGContextClosePath(context);
            CGContextStrokePath(context);
            CGContextBeginPath(context);
            break;
        case 'U':
            CGContextStrokePath(context);
            CGContextBeginPath(context);
            break;
        default:
            break;
        }
    }
}

