UIImage *NoshiTabIconImage(NoshiTabIcon icon, UIColor *color) {
    UIGraphicsBeginImageContextWithOptions(CGSizeMake(ICON_SIDE, ICON_SIDE), NO, 0);
    CGContextRef context = UIGraphicsGetCurrentContext();
    CGContextSetFillColorWithColor(context, color.CGColor);
    CGContextSetStrokeColorWithColor(context, color.CGColor);
    switch (icon) {
    case NoshiTabIconContacts:
        CGContextSaveGState(context);
        CGContextScaleCTM(context, 0.336f, 0.336f);
        CGContextTranslateCTM(context, -0.33f, -0.33f);
        NoshiDrawOutline(context, NoshiContactsOutline);
        CGContextRestoreGState(context);
        CGContextSetLineWidth(context, 1.33f);
        CGContextStrokeEllipseInRect(context, CGRectMake(3.5f, 3.83f, 24, 24));
        break;
    case NoshiTabIconCalls:
        CGContextTranslateCTM(context, 4, 4);
        CGContextScaleCTM(context, 0.3333f, 0.3333f);
        NoshiDrawOutline(context, NoshiCallsOutline);
        break;
    case NoshiTabIconChats:
        CGContextScaleCTM(context, 0.3333f, 0.3333f);
        NoshiDrawOutline(context, NoshiChatsOutline);
        break;
    case NoshiTabIconSettings:
        /* the gear with a hole in it and the hands of a clock cut out of the disc that fills the hole */
        CGContextSaveGState(context);
        CGContextScaleCTM(context, 0.333333f, 0.333333f);
        NoshiDrawOutline(context, NoshiGearOutline);
        CGContextRestoreGState(context);
        CGContextSetBlendMode(context, kCGBlendModeClear);
        CGContextFillEllipseInRect(context, CGRectMake(6.5f, 6.83f, 17.67f, 17.67f));
        CGContextSetBlendMode(context, kCGBlendModeNormal);
        CGContextFillEllipseInRect(context, CGRectMake(8, 8.33f, 14.67f, 14.67f));
        CGContextSetBlendMode(context, kCGBlendModeClear);
        CGContextScaleCTM(context, 0.333333f, 0.333333f);
        NoshiDrawOutline(context, NoshiGearInner);
        break;
    }
    UIImage *image = UIGraphicsGetImageFromCurrentImageContext();
    UIGraphicsEndImageContext();
    return image;
}
